-- PREPARED ONLY: Y-01..Y-12 connected Web/Desktop technical evidence workspace.
-- Not applied. Existing operations, release, error, backup, restore and audit originals are read only.
-- Runtime gates still required: PostgreSQL/PostgREST/RLS/grants, two sessions, lock/rollback,
-- legacy/native writers, provider sandboxes, browser/layout and qualified care/technical/legal acceptance.
begin;
create schema if not exists technical_evidence_private;
revoke all on schema technical_evidence_private from public,anon,authenticated;
create table if not exists technical_evidence_private.roots(tenant_id uuid primary key,head_id uuid,updated_at timestamptz not null default clock_timestamp());
create table if not exists technical_evidence_private.events(id uuid primary key,tenant_id uuid not null,sequence bigint not null,previous_id uuid,request_id uuid not null,actor_id uuid not null,actor_name text not null,occurred_at timestamptz not null,recorded_at timestamptz not null default clock_timestamp(),kind text not null,command jsonb not null,unique(tenant_id,sequence),unique(tenant_id,request_id));
alter table technical_evidence_private.roots enable row level security;alter table technical_evidence_private.events enable row level security;
revoke all on all tables in schema technical_evidence_private from public,anon,authenticated;
create or replace function technical_evidence_private.immutable()returns trigger language plpgsql security definer set search_path='' as $$begin raise exception using errcode='P0P01',message='Technik- und Betriebsverlauf bleibt unveränderlich.';end$$;
drop trigger if exists technical_evidence_roots_delete on technical_evidence_private.roots;create trigger technical_evidence_roots_delete before delete on technical_evidence_private.roots for each row execute function technical_evidence_private.immutable();
drop trigger if exists technical_evidence_events_immutable on technical_evidence_private.events;create trigger technical_evidence_events_immutable before update or delete on technical_evidence_private.events for each row execute function technical_evidence_private.immutable();

create or replace function technical_evidence_private.profile_has(t uuid,a uuid,keys text[])returns boolean language sql stable set search_path='' as $$
select exists(select 1 from public.profiles p join public.roles r on r.id=p.role_id where p.id=a and p.tenant_id=t and p.is_active and p.status='active'and not exists(select 1 from unnest(keys)k where not case when exists(select 1 from public.role_permission_sets z where z.tenant_id=t and z.role_key=r.key)then exists(select 1 from public.role_permission_sets z where z.tenant_id=t and z.role_key=r.key and z.permission_key=k)else exists(select 1 from public.role_permissions z where z.role_id=r.id and z.permission_key=k)end))$$;
create or replace function technical_evidence_private.kind_right(k text)returns text language sql immutable set search_path='' as $$select case
 when k in('persistence_snapshot','persistence_error','uncertain_write_receipt','concurrency_conflict','conflict_resolution','outbox_entry','sync_result','deletion_request','import_manifest','mapping_review','migration_result','rollback_result','backup_manifest','restore_drill','browser_layout_evidence','accessibility_evidence','large_list_snapshot','performance_measurement','release_candidate','acceptance_gate','crash_checkpoint','recovery_result','android_contract_review','correction')then'release.manage'end$$;
create or replace function technical_evidence_private.extra_rights(k text)returns text[] language sql immutable set search_path='' as $$select case when technical_evidence_private.kind_right(k)is not null then array['security.manage']::text[]else array[]::text[]end$$;
create or replace function technical_evidence_private.actor(t uuid,a uuid,k text default null)returns text language plpgsql security definer set search_path='' as $$
declare sid uuid;n text;permission text;required text[]:=array['release.view','security.view'];begin
 if auth.uid()is null or public.resolve_current_profile_id()is distinct from a or public.current_tenant_id()is distinct from t or coalesce((auth.jwt()->>'exp')::bigint,0)<=extract(epoch from clock_timestamp())then raise exception using errcode='42501',message='Aktuelles eigenes Konto fehlt.';end if;
 sid:=nullif(auth.jwt()->>'session_id','')::uuid;perform 1 from auth.sessions s where s.id=sid and s.user_id=auth.uid()and(s.not_after is null or s.not_after>clock_timestamp())for share;if not found then raise exception using errcode='42501',message='Aktuelle native Sitzung fehlt.';end if;
 permission:=technical_evidence_private.kind_right(k);if k is not null and permission is null then raise exception using errcode='22023',message='Technik- und Betriebsvorgang ist unbekannt.';end if;if permission is not null then required:=required||permission||technical_evidence_private.extra_rights(k);lock table public.roles,public.role_permissions,public.role_permission_sets in share mode;end if;
 select coalesce(nullif(btrim(p.display_name),''),'Name nicht bestätigt')into n from public.profiles p join public.roles r on r.id=p.role_id where p.id=a and p.tenant_id=t and p.is_active and p.status='active'and(p.auth_user_id is null or p.auth_user_id=auth.uid())for share of p,r;
 if n is null or not technical_evidence_private.profile_has(t,a,required)then raise exception using errcode='42501',message='Aktuelle Release- oder Securityrechte fehlen.';end if;foreach permission in array required loop if public.has_permission(permission)is not true then raise exception using errcode='42501',message='Nativer Rechtezugang fehlt.';end if;end loop;return n;
end$$;

create or replace function technical_evidence_private.sources(t uuid)returns jsonb language sql security definer set search_path='' as $$with s as(
 select'system_health'::text kind,x.id,to_jsonb(x)snapshot from public.system_health_checks x where x.tenant_id=t
 union all select'system_error',x.id,to_jsonb(x)from public.system_error_logs x where x.tenant_id=t
 union all select'incident_ticket',x.id,to_jsonb(x)from public.incident_tickets x where x.tenant_id=t
 union all select'backup_status',x.id,to_jsonb(x)from public.backup_status_records x where x.tenant_id=t
 union all select'restore_test',x.id,to_jsonb(x)from public.restore_test_records x where x.tenant_id=t
 union all select'maintenance_window',x.id,to_jsonb(x)from public.maintenance_windows x where x.tenant_id=t
 union all select'release_note',x.id,to_jsonb(x)from public.release_notes x where x.tenant_id=t
 union all select'operations_audit',x.id,to_jsonb(x)from public.operations_audit_events x where x.tenant_id=t
 union all select'release_package',x.id,to_jsonb(x)from public.release_packages x where x.tenant_id=t
)select coalesce(jsonb_agg(jsonb_build_object('kind',kind,'id',id,'snapshot',snapshot)order by kind,id),'[]'::jsonb)from s$$;

create or replace function technical_evidence_private.source_rules(k text)returns jsonb language sql immutable set search_path='' as $$select case k
 when'persistence_snapshot'then'{"record":["operations_audit","release_package"],"health":["system_health"]}'
 when'persistence_error'then'{"error":["system_error"],"record":["operations_audit","release_package"]}'
 when'uncertain_write_receipt'then'{"error":["system_error"],"audit":["operations_audit"]}'
 when'concurrency_conflict'then'{"base":["operations_audit","release_package"],"current":["operations_audit","release_package"]}'
 when'conflict_resolution'then'{"conflict":["system_error","operations_audit"],"decisionSource":["operations_audit"]}'
 when'outbox_entry'then'{"entry":["system_error","operations_audit"],"device":["system_health"]}'
 when'sync_result'then'{"entry":["system_error","operations_audit"],"receipt":["operations_audit"]}'
 when'deletion_request'then'{"entry":["system_error","operations_audit"],"audit":["operations_audit"]}'
 when'import_manifest'then'{"source":["operations_audit","release_package"],"audit":["operations_audit"]}'
 when'mapping_review'then'{"manifest":["operations_audit","release_package"],"audit":["operations_audit"]}'
 when'migration_result'then'{"manifest":["operations_audit","release_package"],"run":["operations_audit","system_error"]}'
 when'rollback_result'then'{"run":["operations_audit","system_error"],"audit":["operations_audit"]}'
 when'backup_manifest'then'{"backup":["backup_status"],"audit":["operations_audit"]}'
 when'restore_drill'then'{"backup":["backup_status"],"restore":["restore_test"]}'
 when'browser_layout_evidence'then'{"release":["release_package","release_note"],"audit":["operations_audit"]}'
 when'accessibility_evidence'then'{"release":["release_package","release_note"],"audit":["operations_audit"]}'
 when'large_list_snapshot'then'{"audit":["operations_audit"],"health":["system_health"]}'
 when'performance_measurement'then'{"snapshot":["operations_audit"],"release":["release_package","release_note"]}'
 when'release_candidate'then'{"release":["release_package"],"note":["release_note"]}'
 when'acceptance_gate'then'{"release":["release_package"],"audit":["operations_audit"]}'
 when'crash_checkpoint'then'{"error":["system_error"],"audit":["operations_audit"]}'
 when'recovery_result'then'{"error":["system_error"],"audit":["operations_audit"]}'
 when'android_contract_review'then'{"release":["release_package"],"audit":["operations_audit"]}'
 when'correction'then'{}'end::jsonb$$;
create or replace function technical_evidence_private.field_keys(k text)returns text[] language sql immutable set search_path='' as $$select case k
 when'persistence_snapshot'then array['versionId','contentSha256','state']when'persistence_error'then array['phase','outcome','traceSha256']when'uncertain_write_receipt'then array['requestId','decision','requestSha256']
 when'concurrency_conflict'then array['expectedVersion','actualVersion','comparisonSha256']when'conflict_resolution'then array['decision','resultSha256','reason']
 when'outbox_entry'then array['payloadSha256','createdAt','state']when'sync_result'then array['outcome','observedAt','receiptSha256']when'deletion_request'then array['state','requestedAt','scopeSha256']
 when'import_manifest'then array['formatVersion','sourceSha256','recordCount']when'mapping_review'then array['mappingSha256','unitPolicySha256','decision']when'migration_result'then array['outcome','acceptedCount','rejectedCount','resultSha256']when'rollback_result'then array['outcome','verifiedAt','reportSha256']
 when'backup_manifest'then array['archiveSha256','manifestSha256','recordCount','state']when'restore_drill'then array['outcome','startedAt','completedAt','reportSha256']
 when'browser_layout_evidence'then array['viewport','zoom','traceSha256','screenshotSha256']when'accessibility_evidence'then array['assistiveTechnology','actionInventorySha256','traceSha256','decision']
 when'large_list_snapshot'then array['snapshotSha256','recordCount','pagination']when'performance_measurement'then array['viewport','responseBudgetMs','interactionBudgetMs','traceSha256','decision']
 when'release_candidate'then array['commitSha256','artifactSha256','channel','state']when'acceptance_gate'then array['gate','decision','evidenceSha256']when'crash_checkpoint'then array['checkpointId','savedStateSha256','openWorkSha256','observedAt']when'recovery_result'then array['checkpointId','outcome','restoredStateSha256','resumedAt']when'android_contract_review'then array['apiContractSha256','readerWriterMatrixSha256','decision','limitations']
 when'correction'then array['targetId','reason','evidenceSha256']end$$;

create or replace function technical_evidence_private.validate_command(cmd jsonb,src jsonb)returns void language plpgsql set search_path='' as $$declare k text:=cmd->>'kind';p jsonb:=cmd->'payload';rules jsonb:=technical_evidence_private.source_rules(k);actual text[];expected text[];entry record;v jsonb;begin
select array_agg(x order by x)into actual from jsonb_object_keys(cmd)x;if jsonb_typeof(cmd)is distinct from'object'or actual is distinct from array['actorId','eventId','expectedHeadId','kind','note','occurredAt','payload','requestId','tenantId','version']::text[]or cmd->>'version'<>'2026-10-16.1'or technical_evidence_private.kind_right(k)is null or cmd->>'requestId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'or cmd->>'eventId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'or cmd->>'tenantId'!~'^[0-9a-f-]{36}$'or cmd->>'actorId'!~'^[0-9a-f-]{36}$'or(cmd->'expectedHeadId'<>'null'::jsonb and cmd->>'expectedHeadId'!~'^[0-9a-f-]{36}$')or cmd->>'occurredAt'!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})$'or nullif(btrim(cmd->>'note'),'')is null or length(cmd->>'note')>4000 or jsonb_typeof(p)is distinct from'object'or rules is null then raise exception using errcode='22023',message='Technik- und Betriebsanfrage ist unvollständig.';end if;
 select array_agg(key order by key)into expected from(select jsonb_object_keys(rules)key union all select unnest(technical_evidence_private.field_keys(k)))q;select array_agg(x order by x)into actual from jsonb_object_keys(p)x;if actual is distinct from expected then raise exception using errcode='22023',message='Vorgangsfelder sind unvollständig oder enthalten Fremdfelder.';end if;
 for entry in select key,value from jsonb_each(rules)loop v:=p->entry.key;if jsonb_typeof(v)is distinct from'object'or(select array_agg(x order by x)from jsonb_object_keys(v)x)is distinct from array['id','kind','snapshot']::text[]or not exists(select 1 from jsonb_array_elements(entry.value)x where x#>>'{}'=v->>'kind')or v->>'id'!~'^[0-9a-f-]{36}$'or jsonb_typeof(v->'snapshot')is distinct from'object'or v#>>'{snapshot,id}'is distinct from v->>'id'or not exists(select 1 from jsonb_array_elements(src)x where x=v)then raise exception using errcode='40001',message='Originalquelle ist falsch, geändert oder nicht mehr zugänglich.';end if;end loop;
 for entry in select x key from unnest(technical_evidence_private.field_keys(k))x loop if nullif(btrim(p->>entry.key),'')is null then raise exception using errcode='22023',message='Pflichtangabe fehlt.';end if;if entry.key~'(Sha256)$'and(p->>entry.key)!~'^[0-9a-f]{64}$'then raise exception using errcode='22023',message='Fingerabdruck ist ungültig.';elsif entry.key in('createdAt','observedAt','requestedAt','verifiedAt','startedAt','completedAt','resumedAt')and(p->>entry.key)!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})$'then raise exception using errcode='22007',message='Zeitpunkt ist ungültig.';elsif entry.key in('targetId','requestId','checkpointId')and(p->>entry.key)!~'^[0-9a-f-]{36}$'then raise exception using errcode='22P02',message='UUID ist ungültig.';end if;end loop;
end$$;

create or replace function technical_evidence_private.event_json(e technical_evidence_private.events)returns jsonb language sql immutable set search_path='' as $$select jsonb_build_object('id',e.id,'sequence',e.sequence,'previousId',e.previous_id,'tenantId',e.tenant_id,'actorId',e.actor_id,'actorName',e.actor_name,'recordedAt',to_char(e.recorded_at at time zone'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'command',e.command)$$;
create or replace function technical_evidence_private.history(t uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare e technical_evidence_private.events%rowtype;head uuid;prev uuid;n bigint:=0;rows jsonb:='[]';begin select r.head_id into head from technical_evidence_private.roots r where r.tenant_id=t;for e in select*from technical_evidence_private.events z where z.tenant_id=t order by z.sequence loop if e.sequence<>n+1 or e.previous_id is distinct from prev or e.command->>'eventId'is distinct from e.id::text or e.command->>'tenantId'is distinct from t::text or e.command->>'actorId'is distinct from e.actor_id::text or(e.command->>'expectedHeadId')is distinct from prev::text then raise exception using errcode='23514',message='Technik- und Betriebsverlauf ist widersprüchlich.';end if;rows:=rows||jsonb_build_array(technical_evidence_private.event_json(e));prev:=e.id;n:=n+1;end loop;if head is distinct from prev then raise exception using errcode='23514',message='Technik- und Betriebsverlaufskopf ist unvollständig.';end if;return jsonb_build_object('version','2026-10-16.1','tenantId',t,'count',n,'headId',head,'events',rows);end$$;
create or replace function technical_evidence_private.read_context(t uuid,a uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare n text;src jsonb;begin n:=technical_evidence_private.actor(t,a,null);src:=technical_evidence_private.sources(t);return jsonb_build_object('version','2026-10-16.1','tenantId',t,'actorId',a,'loadedAt',to_char(clock_timestamp()at time zone'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'sources',jsonb_build_object('count',jsonb_array_length(src),'rows',src),'history',technical_evidence_private.history(t));end$$;
create or replace function technical_evidence_private.commit_event(cmd jsonb)returns jsonb language plpgsql security definer set search_path='' as $$declare t uuid:=(cmd->>'tenantId')::uuid;a uuid:=(cmd->>'actorId')::uuid;rid uuid:=(cmd->>'requestId')::uuid;eid uuid:=(cmd->>'eventId')::uuid;n text;root technical_evidence_private.roots%rowtype;e technical_evidence_private.events%rowtype;src jsonb;begin n:=technical_evidence_private.actor(t,a,cmd->>'kind');perform pg_advisory_xact_lock(hashtextextended('technical-evidence:'||t::text,0));insert into technical_evidence_private.roots(tenant_id)values(t)on conflict do nothing;select*into root from technical_evidence_private.roots r where r.tenant_id=t for update;select*into e from technical_evidence_private.events z where z.tenant_id=t and z.request_id=rid;if e.id is not null then if e.command is distinct from cmd then raise exception using errcode='23505',message='Anfragekennung gehört zu anderem Inhalt.';end if;return jsonb_build_object('version','2026-10-16.1','requestId',rid,'command',e.command,'event',technical_evidence_private.event_json(e));end if;src:=technical_evidence_private.sources(t);perform technical_evidence_private.validate_command(cmd,src);if(cmd->>'expectedHeadId')is distinct from root.head_id::text then raise exception using errcode='40001',message='Technik- und Betriebsverlauf wurde geändert.';end if;if cmd->>'kind'='correction'and not exists(select 1 from technical_evidence_private.events x where x.tenant_id=t and x.id=(cmd#>>'{payload,targetId}')::uuid and x.kind<>'correction'and not exists(select 1 from technical_evidence_private.events z where z.tenant_id=t and z.kind='correction'and z.command#>>'{payload,targetId}'=x.id::text))then raise exception using errcode='23514',message='Nur ein vorhandenes unberichtigtes Original kann berichtigt werden.';end if;insert into technical_evidence_private.events(id,tenant_id,sequence,previous_id,request_id,actor_id,actor_name,occurred_at,kind,command)values(eid,t,coalesce((select max(sequence)+1 from technical_evidence_private.events where tenant_id=t),1),root.head_id,rid,a,n,(cmd->>'occurredAt')::timestamptz,cmd->>'kind',cmd)returning*into e;update technical_evidence_private.roots set head_id=eid,updated_at=clock_timestamp()where tenant_id=t;return jsonb_build_object('version','2026-10-16.1','requestId',rid,'command',cmd,'event',technical_evidence_private.event_json(e));end$$;
create or replace function technical_evidence_private.confirm_event(t uuid,a uuid,rid uuid,cmd jsonb)returns jsonb language plpgsql security definer set search_path='' as $$declare e technical_evidence_private.events%rowtype;begin perform technical_evidence_private.actor(t,a,null);select*into e from technical_evidence_private.events z where z.tenant_id=t and z.request_id=rid;if e.id is null or e.command is distinct from cmd or e.actor_id<>a then raise exception using errcode='P0P01',message='Passende native Quittung fehlt.';end if;return jsonb_build_object('version','2026-10-16.1','requestId',rid,'command',e.command,'event',technical_evidence_private.event_json(e));end$$;
create or replace function public.web_technical_evidence_workspace_context(p_tenant_id uuid,p_actor_id uuid)returns jsonb language sql security invoker set search_path='' as $$select technical_evidence_private.read_context(p_tenant_id,p_actor_id)$$;
create or replace function public.web_commit_technical_evidence_event(p_command jsonb)returns jsonb language sql security invoker set search_path='' as $$select technical_evidence_private.commit_event(p_command)$$;
create or replace function public.web_confirm_technical_evidence_event(p_tenant_id uuid,p_actor_id uuid,p_request_id uuid,p_command jsonb)returns jsonb language sql security invoker set search_path='' as $$select technical_evidence_private.confirm_event(p_tenant_id,p_actor_id,p_request_id,p_command)$$;
revoke all on function public.web_technical_evidence_workspace_context(uuid,uuid),public.web_commit_technical_evidence_event(jsonb),public.web_confirm_technical_evidence_event(uuid,uuid,uuid,jsonb)from public,anon;
grant usage on schema technical_evidence_private to authenticated;
grant execute on function technical_evidence_private.read_context(uuid,uuid),technical_evidence_private.commit_event(jsonb),technical_evidence_private.confirm_event(uuid,uuid,uuid,jsonb)to authenticated;
grant execute on function public.web_technical_evidence_workspace_context(uuid,uuid),public.web_commit_technical_evidence_event(jsonb),public.web_confirm_technical_evidence_event(uuid,uuid,uuid,jsonb)to authenticated;
commit;
